  1→"use client";
  2→
  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { createPortal } from "react-dom";
 17→import { EllipsisVertical, Pin, Snowflake, Plus } from "lucide-react";
 18→import type { AgentStatus, Workspace } from "@/lib/types";
 19→import type { AgentClientState } from "@/hooks/use-websocket";
 20→import { cn } from "@/lib/utils";
 21→import { WorkspaceSwitcher } from "./workspace-switcher";
 22→
 23→/** Status dot color + optional pulse animation. */
 24→const STATUS_DOT: Record<AgentStatus, string> = {
 25→  idle: "bg-muted-foreground",
 26→  spawning: "bg-yellow-500 animate-pulse",
 27→  connected: "bg-green-500",
 28→  thinking: "bg-blue-500 animate-pulse",
 29→  done: "bg-muted-foreground",
 30→  disconnected: "bg-orange-500 animate-pulse",
 31→  error: "bg-red-500",
 32→};
 33→
 34→/** Statuses where the CLI is actively running and can be killed. */
 35→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 36→/** Statuses considered archived (session ended, read-only). */
 37→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 38→
 39→interface ContextMenuState {
 40→  agentId: string;
 41→  x: number;
 42→  y: number;
 43→}
 44→
 45→export function AgentSidebar({
 46→  agents,
 47→  agentOrder,
 48→  activeAgentId,
 49→  loading,
 50→  onSelect,
 51→  onNewAgent,
 52→  onKill,
 53→  onDelete,
 54→  onRename,
 55→  onClearHistory,
 56→  onPin,
 57→  onIcebox,
 58→  workspaces,
 59→  activeWorkspaceId,
 60→  onSelectWorkspace,
 61→  onRenameWorkspace,
 62→  onDeleteWorkspace,
 63→  onOpenFolder,
 64→}: {
 65→  agents: Map<string, AgentClientState>;
 66→  agentOrder: string[];
 67→  activeAgentId: string | null;
 68→  loading?: boolean;
 69→  onSelect: (agentId: string | null) => void;
 70→  onNewAgent: () => void;
 71→  onKill: (agentId: string) => void;
 72→  onDelete: (agentId: string) => void;
 73→  onRename: (agentId: string, label: string) => void;
 74→  onClearHistory: (agentId: string) => void;
 75→  onPin: (agentId: string, pinned: boolean) => void;
 76→  onIcebox: (agentId: string, iceboxed: boolean) => void;
 77→  workspaces: Workspace[];
 78→  activeWorkspaceId: string | null;
 79→  onSelectWorkspace: (workspaceId: string | null) => void;
 80→  onRenameWorkspace: (workspaceId: string, name: string) => void;
 81→  onDeleteWorkspace: (workspaceId: string) => void;
 82→  onOpenFolder: () => void;
 83→}) {
 84→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 85→  const [renamingId, setRenamingId] = useState<string | null>(null);
 86→  const menuRef = useRef<HTMLDivElement>(null);
 87→
 88→  // Sort helper: most recent first by createdAt
 89→  const byRecency = (a: string, b: string) => {
 90→    const ca = agents.get(a)?.createdAt ?? 0;
 91→    const cb = agents.get(b)?.createdAt ?? 0;
 92→    return cb - ca;
 93→  };
 94→
 95→  // Split agents into pinned, active, icebox, and archived
 96→  const pinnedIds = agentOrder
 97→    .filter((id) => {
 98→      const a = agents.get(id);
 99→      return a && a.pinned && !a.iceboxed;
100→    })
101→    .sort(byRecency);
102→  const activeIds = agentOrder
103→    .filter((id) => {
104→      const a = agents.get(id);
105→      return a && !a.pinned && !a.iceboxed && !ARCHIVED.has(a.status);
106→    })
107→    .sort(byRecency);
108→  const iceboxIds = agentOrder
109→    .filter((id) => {
110→      const a = agents.get(id);
111→      return a && a.iceboxed;
112→    })
113→    .sort(byRecency);
114→  const archivedIds = agentOrder
115→    .filter((id) => {
116→      const a = agents.get(id);
117→      return a && !a.pinned && !a.iceboxed && ARCHIVED.has(a.status);
118→    })
119→    .sort(byRecency);
120→
121→  // Close context menu on click-outside or Escape
122→  useEffect(() => {
123→    if (!ctxMenu) return;
124→    function handleClick(e: MouseEvent) {
125→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
126→        setCtxMenu(null);
127→      }
128→    }
129→    function handleKey(e: KeyboardEvent) {
130→      if (e.key === "Escape") setCtxMenu(null);
131→    }
132→    document.addEventListener("mousedown", handleClick);
133→    document.addEventListener("keydown", handleKey);
134→    return () => {
135→      document.removeEventListener("mousedown", handleClick);
136→      document.removeEventListener("keydown", handleKey);
137→    };
138→  }, [ctxMenu]);
139→
140→  const openMenu = useCallback((agentId: string, x: number, y: number) => {
141→    setCtxMenu({ agentId, x, y });
142→  }, []);
143→
144→  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
145→    e.preventDefault();
146→    openMenu(agentId, e.clientX, e.clientY);
147→  }, [openMenu]);
148→
149→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
150→    e.stopPropagation();
151→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
152→    openMenu(agentId, rect.right, rect.bottom);
153→  }, [openMenu]);
154→
155→  const closeMenu = useCallback(() => setCtxMenu(null), []);
156→
157→  function renderAgentRow(id: string, dimmed: boolean) {
158→    const agent = agents.get(id);
159→    if (!agent) return null;
160→    const isActive = id === activeAgentId;
161→    return (
162→      <div
163→        key={id}
164→        onClick={() => onSelect(id)}
165→        onContextMenu={(e) => handleContextMenu(e, id)}
166→        className={cn(
167→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
168→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
169→          dimmed && "opacity-60"
170→        )}
171→      >
172→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
173→          <span className="flex items-center gap-2">
174→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
175→            {renamingId === id ? (
176→              <RenameInput
177→                initialValue={agent.label}
178→                onConfirm={(label) => {
179→                  onRename(id, label);
180→                  setRenamingId(null);
181→                }}
182→                onCancel={() => setRenamingId(null)}
183→              />
184→            ) : (
185→              <span className="truncate" title={agent.label || "new agent"}>{agent.label || "new agent"}</span>
186→            )}
187→            {agent.pinned && (
188→              <Pin className="size-2.5 shrink-0 text-muted-foreground" />
189→            )}
190→            {agent.iceboxed && (
191→              <Snowflake className="size-2.5 shrink-0 text-muted-foreground" />
192→            )}
193→          </span>
194→          {agent.tmuxSession && (
195→            <span className="pl-4 text-[10px] text-muted-foreground truncate" title={agent.tmuxSession}>
196→              {agent.tmuxSession}
197→            </span>
198→          )}
199→        </div>
200→        <button
201→          onClick={(e) => handleMenuButton(e, id)}
202→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
203→          aria-label="Agent menu"
204→        >
205→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
206→        </button>
207→      </div>
208→    );
209→  }
210→
211→  return (
212→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
213→      {/* Workspace switcher */}
214→      <div className="border-b">
215→        <WorkspaceSwitcher
216→          workspaces={workspaces}
217→          activeWorkspaceId={activeWorkspaceId}
218→          onSelect={onSelectWorkspace}
219→          onRename={onRenameWorkspace}
220→          onDelete={onDeleteWorkspace}
221→          onOpenFolder={onOpenFolder}
222→        />
223→      </div>
224→
225→      {/* Header */}
226→      <div className="flex items-center justify-between px-3 py-2">
227→        <span className="text-xs font-semibold">agents</span>
228→        <button
229→          onClick={onNewAgent}
230→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
231→          aria-label="New agent"
232→        >
233→          <Plus className="size-3.5" />
234→        </button>
235→      </div>
236→
237→      {/* Agent list */}
238→      <div className="flex-1 overflow-y-auto">
239→        {loading ? (
240→          <div className="space-y-1 px-3 py-2">
241→            {[...Array(4)].map((_, i) => (
242→              <div key={i} className="flex items-center gap-2 py-2">
243→                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
244→                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
245→              </div>
246→            ))}
247→          </div>
248→        ) : agentOrder.length === 0 ? (
249→          <div className="px-3 py-4 text-xs text-muted-foreground">
250→            No agents yet
251→          </div>
252→        ) : null}
253→
254→        {/* Pinned agents */}
255→        {pinnedIds.length > 0 && (
256→          <>
257→            <div className="flex items-center gap-2 px-3 pt-2 pb-1">
258→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">pinned</span>
259→              <div className="flex-1 border-t" />
260→            </div>
261→            {pinnedIds.map((id) => renderAgentRow(id, false))}
262→          </>
263→        )}
264→
265→        {/* Active agents */}
266→        {activeIds.length > 0 && (
267→          <>
268→            {pinnedIds.length > 0 && (
269→              <div className="flex items-center gap-2 px-3 pt-3 pb-1">
270→                <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">active</span>
271→                <div className="flex-1 border-t" />
272→              </div>
273→            )}
274→            {activeIds.map((id) => renderAgentRow(id, false))}
275→          </>
276→        )}
277→
278→        {/* Icebox agents */}
279→        {iceboxIds.length > 0 && (
280→          <>
281→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
282→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">icebox</span>
283→              <div className="flex-1 border-t" />
284→            </div>
285→            {iceboxIds.map((id) => renderAgentRow(id, true))}
286→          </>
287→        )}
288→
289→        {/* Archived divider + agents */}
290→        {archivedIds.length > 0 && (
291→          <>
292→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
293→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
294→              <div className="flex-1 border-t" />
295→            </div>
296→            {archivedIds.map((id) => renderAgentRow(id, true))}
297→          </>
298→        )}
299→      </div>
300→
301→      {/* Context menu — portaled to body to escape sidebar stacking context */}
302→      {ctxMenu && (() => {
303→        const agent = agents.get(ctxMenu.agentId);
304→        if (!agent) return null;
305→        return createPortal(
306→          <div
307→            ref={menuRef}
308→            className="fixed z-[9999] min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
309→            style={{ left: ctxMenu.x, top: ctxMenu.y }}
310→          >
311→            <ContextMenuItem
312→              label={agent.pinned ? "Unpin" : "Pin"}
313→              onClick={() => {
314→                onPin(ctxMenu.agentId, !agent.pinned);
315→                closeMenu();
316→              }}
317→            />
318→            <ContextMenuItem
319→              label={agent.iceboxed ? "Un-icebox" : "Icebox"}
320→              onClick={() => {
321→                onIcebox(ctxMenu.agentId, !agent.iceboxed);
322→                closeMenu();
323→              }}
324→            />
325→            <ContextMenuItem
326→              label="Rename"
327→              onClick={() => {
328→                setRenamingId(ctxMenu.agentId);
329→                closeMenu();
330→              }}
331→            />
332→            {KILLABLE.has(agent.status) && (
333→              <ContextMenuItem
334→                label="Kill"
335→                onClick={() => {
336→                  onKill(ctxMenu.agentId);
337→                  closeMenu();
338→                }}
339→              />
340→            )}
341→            <ContextMenuItem
342→              label="Clear History"
343→              onClick={() => {
344→                onClearHistory(ctxMenu.agentId);
345→                closeMenu();
346→              }}
347→            />
348→            <div className="my-1 border-t" />
349→            <ContextMenuItem
350→              label="Delete"
351→              destructive
352→              onClick={() => {
353→                closeMenu();
354→                if (confirm("Delete this agent? This cannot be undone.")) {
355→                  onDelete(ctxMenu.agentId);
356→                }
357→              }}
358→            />
359→          </div>,
360→          document.body
361→        );
362→      })()}
363→    </div>
364→  );
365→}
366→
367→/** A single item in the context menu. */
368→function ContextMenuItem({
369→  label,
370→  onClick,
371→  destructive,
372→}: {
373→  label: string;
374→  onClick: () => void;
375→  destructive?: boolean;
376→}) {
377→  return (
378→    <button
379→      onClick={onClick}
380→      className={cn(
381→        "flex w-full px-3 py-1.5 text-xs transition-colors",
382→        destructive
383→          ? "text-red-500 hover:bg-red-500/10"
384→          : "hover:bg-accent"
385→      )}
386→    >
387→      {label}
388→    </button>
389→  );
390→}
391→
392→/** Inline input for renaming an agent. */
393→function RenameInput({
394→  initialValue,
395→  onConfirm,
396→  onCancel,
397→}: {
398→  initialValue: string;
399→  onConfirm: (value: string) => void;
400→  onCancel: () => void;
401→}) {
402→  const [value, setValue] = useState(initialValue);
403→  const inputRef = useRef<HTMLInputElement>(null);
404→
405→  useEffect(() => {
406→    inputRef.current?.focus();
407→    inputRef.current?.select();
408→  }, []);
409→
410→  function handleKeyDown(e: React.KeyboardEvent) {
411→    e.stopPropagation();
412→    if (e.key === "Enter") {
413→      const trimmed = value.trim();
414→      if (trimmed) onConfirm(trimmed);
415→      else onCancel();
416→    } else if (e.key === "Escape") {
417→      onCancel();
418→    }
419→  }
420→
421→  return (
422→    <input
423→      ref={inputRef}
424→      type="text"
425→      value={value}
426→      onChange={(e) => setValue(e.target.value)}
427→      onKeyDown={handleKeyDown}
428→      onBlur={() => {
429→        const trimmed = value.trim();
430→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
431→        else onCancel();
432→      }}
433→      onClick={(e) => e.stopPropagation()}
434→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
435→    />
436→  );
437→}
