  1→"use client";
  2→
  3→/**
  4→ * Workspace dropdown in the sidebar header.
  5→ *
  6→ * Shows the active workspace name (or "All Workspaces"), with a dropdown
  7→ * listing all workspaces plus an "Open Folder..." option that triggers
  8→ * the folder browser modal.
  9→ */
 10→
 11→import { useCallback, useEffect, useRef, useState } from "react";
 12→import { ChevronDown, FolderOpen, Pencil, Trash2 } from "lucide-react";
 13→import type { Workspace } from "@/lib/types";
 14→import { cn } from "@/lib/utils";
 15→
 16→export function WorkspaceSwitcher({
 17→  workspaces,
 18→  activeWorkspaceId,
 19→  onSelect,
 20→  onRename,
 21→  onDelete,
 22→  onOpenFolder,
 23→}: {
 24→  workspaces: Workspace[];
 25→  activeWorkspaceId: string | null;
 26→  onSelect: (workspaceId: string | null) => void;
 27→  onRename: (workspaceId: string, name: string) => void;
 28→  onDelete: (workspaceId: string) => void;
 29→  onOpenFolder: () => void;
 30→}) {
 31→  const [open, setOpen] = useState(false);
 32→  const [renamingId, setRenamingId] = useState<string | null>(null);
 33→  const dropdownRef = useRef<HTMLDivElement>(null);
 34→
 35→  const activeWorkspace = activeWorkspaceId
 36→    ? workspaces.find((w) => w.id === activeWorkspaceId)
 37→    : null;
 38→
 39→  // Close on click-outside or Escape
 40→  useEffect(() => {
 41→    if (!open) return;
 42→    function handleClick(e: MouseEvent) {
 43→      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
 44→        setOpen(false);
 45→      }
 46→    }
 47→    function handleKey(e: KeyboardEvent) {
 48→      if (e.key === "Escape") setOpen(false);
 49→    }
 50→    document.addEventListener("mousedown", handleClick);
 51→    document.addEventListener("keydown", handleKey);
 52→    return () => {
 53→      document.removeEventListener("mousedown", handleClick);
 54→      document.removeEventListener("keydown", handleKey);
 55→    };
 56→  }, [open]);
 57→
 58→  const handleSelect = useCallback(
 59→    (id: string | null) => {
 60→      onSelect(id);
 61→      setOpen(false);
 62→    },
 63→    [onSelect]
 64→  );
 65→
 66→  return (
 67→    <div className="relative" ref={dropdownRef}>
 68→      <button
 69→        onClick={() => setOpen((v) => !v)}
 70→        className="flex w-full items-center gap-1.5 rounded px-3 py-2 text-left text-sm transition-colors hover:bg-sidebar-accent"
 71→      >
 72→        <span className="flex min-w-0 flex-1 flex-col">
 73→          <span className="text-primary font-bold text-sm tracking-tight truncate" title={activeWorkspace?.name ?? "All Workspaces"}>
 74→            {activeWorkspace?.name ?? "All Workspaces"}
 75→          </span>
 76→          {activeWorkspace && (
 77→            <span className="text-[10px] text-muted-foreground truncate" title={activeWorkspace.cwd}>
 78→              {activeWorkspace.cwd}
 79→            </span>
 80→          )}
 81→        </span>
 82→        <ChevronDown className={cn("size-3.5 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")} />
 83→      </button>
 84→
 85→      {open && (
 86→        <div className="absolute left-0 top-full z-50 mt-1 w-full min-w-[200px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md">
 87→          {/* All Workspaces */}
 88→          <button
 89→            onClick={() => handleSelect(null)}
 90→            className={cn(
 91→              "flex w-full items-center px-3 py-1.5 text-xs transition-colors hover:bg-accent",
 92→              activeWorkspaceId === null && "bg-accent"
 93→            )}
 94→          >
 95→            All Workspaces
 96→          </button>
 97→
 98→          {workspaces.length > 0 && <div className="my-1 border-t" />}
 99→
100→          {/* Workspace list */}
101→          {workspaces.map((ws) => (
102→            <div
103→              key={ws.id}
104→              className={cn(
105→                "group flex items-center gap-1 px-3 py-1.5 text-xs transition-colors hover:bg-accent cursor-pointer",
106→                activeWorkspaceId === ws.id && "bg-accent"
107→              )}
108→              onClick={() => {
109→                if (renamingId !== ws.id) handleSelect(ws.id);
110→              }}
111→            >
112→              {renamingId === ws.id ? (
113→                <RenameInput
114→                  initialValue={ws.name}
115→                  onConfirm={(name) => {
116→                    onRename(ws.id, name);
117→                    setRenamingId(null);
118→                  }}
119→                  onCancel={() => setRenamingId(null)}
120→                />
121→              ) : (
122→                <>
123→                  <span className="min-w-0 flex-1 truncate" title={ws.name}>{ws.name}</span>
124→                  <button
125→                    onClick={(e) => {
126→                      e.stopPropagation();
127→                      setRenamingId(ws.id);
128→                    }}
129→                    className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-accent group-hover:opacity-100"
130→                    aria-label="Rename workspace"
131→                  >
132→                    <Pencil className="size-3 text-muted-foreground" />
133→                  </button>
134→                  <button
135→                    onClick={(e) => {
136→                      e.stopPropagation();
137→                      if (confirm(`Delete workspace "${ws.name}"?`)) {
138→                        onDelete(ws.id);
139→                      }
140→                    }}
141→                    className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-red-500/10 group-hover:opacity-100"
142→                    aria-label="Delete workspace"
143→                  >
144→                    <Trash2 className="size-3 text-red-500" />
145→                  </button>
146→                </>
147→              )}
148→            </div>
149→          ))}
150→
151→          <div className="my-1 border-t" />
152→
153→          {/* Open Folder */}
154→          <button
155→            onClick={() => {
156→              setOpen(false);
157→              onOpenFolder();
158→            }}
159→            className="flex w-full items-center gap-2 px-3 py-1.5 text-xs transition-colors hover:bg-accent"
160→          >
161→            <FolderOpen className="size-3.5 text-muted-foreground" />
162→            Open Folder...
163→          </button>
164→        </div>
165→      )}
166→    </div>
167→  );
168→}
169→
170→/** Inline input for renaming a workspace. */
171→function RenameInput({
172→  initialValue,
173→  onConfirm,
174→  onCancel,
175→}: {
176→  initialValue: string;
177→  onConfirm: (value: string) => void;
178→  onCancel: () => void;
179→}) {
180→  const [value, setValue] = useState(initialValue);
181→  const inputRef = useRef<HTMLInputElement>(null);
182→
183→  useEffect(() => {
184→    inputRef.current?.focus();
185→    inputRef.current?.select();
186→  }, []);
187→
188→  return (
189→    <input
190→      ref={inputRef}
191→      type="text"
192→      value={value}
193→      onChange={(e) => setValue(e.target.value)}
194→      onKeyDown={(e) => {
195→        e.stopPropagation();
196→        if (e.key === "Enter") {
197→          const trimmed = value.trim();
198→          if (trimmed) onConfirm(trimmed);
199→          else onCancel();
200→        } else if (e.key === "Escape") {
201→          onCancel();
202→        }
203→      }}
204→      onBlur={() => {
205→        const trimmed = value.trim();
206→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
207→        else onCancel();
208→      }}
209→      onClick={(e) => e.stopPropagation()}
210→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
211→    />
212→  );
213→}
