 1→/**
 2→ * File-based workspace persistence for the thos dashboard.
 3→ *
 4→ * Stores all workspaces in a single JSON file at `.thos/workspaces.json`.
 5→ * Workspaces change infrequently so only sync writes are used.
 6→ */
 7→
 8→import { mkdirSync, writeFileSync, readFileSync, existsSync } from "fs";
 9→import { join } from "path";
10→import type { Workspace } from "../lib/types";
11→
12→const THOS_DIR = join(process.cwd(), ".thos");
13→const WORKSPACE_FILE = join(THOS_DIR, "workspaces.json");
14→
15→export class WorkspaceStore {
16→  constructor() {
17→    mkdirSync(THOS_DIR, { recursive: true });
18→  }
19→
20→  /** Load all workspaces from disk. Returns empty array if file missing. */
21→  loadAll(): Workspace[] {
22→    if (!existsSync(WORKSPACE_FILE)) return [];
23→    try {
24→      const raw = readFileSync(WORKSPACE_FILE, "utf-8");
25→      return JSON.parse(raw) as Workspace[];
26→    } catch (err) {
27→      console.error("[workspace-store] failed to load:", err);
28→      return [];
29→    }
30→  }
31→
32→  /** Immediate write. */
33→  saveSync(workspaces: Workspace[]): void {
34→    try {
35→      writeFileSync(WORKSPACE_FILE, JSON.stringify(workspaces, null, 2));
36→    } catch (err) {
37→      console.error("[workspace-store] failed to write:", err);
38→    }
39→  }
40→}
