  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→  Workspace,
 65→} from "@/lib/types";
 66→import { sfxTool, sfxDone, sfxError, sfxQuestion, sfxBegin, sfxSend } from "@/lib/sfx";
 67→
 68→/** Connect to the WS server on the same host the page was loaded from. */
 69→const WS_URL =
 70→  typeof window !== "undefined"
 71→    ? `ws://${window.location.hostname}:9900/browser`
 72→    : "ws://localhost:9900/browser";
 73→
 74→/** Per-agent client state. */
 75→export interface AgentClientState {
 76→  status: AgentStatus;
 77→  messages: ChatMessage[];
 78→  /** Raw Claude NDJSON messages for debug view. */
 79→  rawMessages: ClaudeMessage[];
 80→  label: string;
 81→  tmuxSession: string | null;
 82→  createdAt: number;
 83→  /** Model name from system/init or agent_list. */
 84→  model?: string;
 85→  /** Whether this agent is pinned to the top of the sidebar. */
 86→  pinned?: boolean;
 87→  /** Whether this agent is in the icebox. */
 88→  iceboxed?: boolean;
 89→}
 90→
 91→/**
 92→ * Extract displayable text from a Claude assistant message.
 93→ * Content blocks may be text, tool_use, or tool_result — each is
 94→ * handled defensively since the array structure can vary.
 95→ */
 96→function extractText(msg: ClaudeAssistant): string {
 97→  const blocks = msg.message?.content;
 98→  if (!blocks || !Array.isArray(blocks)) return "";
 99→  return blocks
100→    .map((b) => {
101→      if (b.type === "text") return b.text;
102→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
103→      if (b.type === "tool_result") {
104→        const c = (b as { content?: unknown }).content;
105→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
106→      }
107→      return "";
108→    })
109→    .filter(Boolean)
110→    .join("\n");
111→}
112→
113→/** Module-level counter for generating unique message IDs. */
114→let msgCounter = 0;
115→function nextId() {
116→  return `msg-${Date.now()}-${++msgCounter}`;
117→}
118→
119→/**
120→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
121→ * Used both for live messages and for replaying message_history.
122→ */
123→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
124→  if (relayMsg.type === "relay") {
125→    const msg = relayMsg.message;
126→
127→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
128→      const init = msg as ClaudeSystemInit;
129→      return {
130→        id: nextId(),
131→        role: "system",
132→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
133→        timestamp: Date.now(),
134→      };
135→    }
136→
137→    if (msg.type === "user") {
138→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
139→      // Only render human-typed user messages (string content).
140→      // CLI tool_result messages have array content — these are internal
141→      // protocol messages and are only visible in the raw message viewer.
142→      if (typeof rawContent !== "string") return null;
143→      if (!rawContent.trim()) return null;
144→      return {
145→        id: nextId(),
146→        role: "user",
147→        content: rawContent,
148→        timestamp: Date.now(),
149→      };
150→    }
151→
152→    if (msg.type === "assistant") {
153→      const assistant = msg as ClaudeAssistant;
154→      const text = extractText(assistant);
155→      if (!text) return null;
156→
157→      const blocks = assistant.message?.content ?? [];
158→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
159→
160→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
161→      const resultMap = new Map<string, string>();
162→      for (const b of blocks) {
163→        if (b.type === "tool_result") {
164→          const tr = b as { tool_use_id?: string; content?: unknown };
165→          if (tr.tool_use_id) {
166→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
167→            const firstLine = raw.split("\n")[0];
168→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
169→          }
170→        }
171→      }
172→
173→      // Build ToolCallInfo for each tool_use block. For file-modifying tools
174→      // (Edit, Write, MultiEdit), the raw `input` object is preserved so that
175→      // DiffViewer can render syntax-highlighted before/after diffs. Other
176→      // tools only keep the name and result preview to avoid carrying
177→      // unnecessary data (e.g. Read file contents, Bash output).
178→      const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
179→      const toolCalls: ToolCallInfo[] = blocks
180→        .filter((b) => b.type === "tool_use")
181→        .map((b) => {
182→          const tu = b as { name: string; id: string; input: Record<string, unknown> };
183→          const info: ToolCallInfo = {
184→            name: tu.name,
185→            toolUseId: tu.id,
186→            resultPreview: resultMap.get(tu.id),
187→          };
188→          if (DIFF_TOOLS.has(tu.name)) {
189→            info.input = tu.input;
190→          }
191→          return info;
192→        });
193→      const isToolOnly = !hasText && toolCalls.length > 0;
194→
195→      return {
196→        id: nextId(),
197→        role: "assistant",
198→        content: text,
199→        timestamp: Date.now(),
200→        toolCalls,
201→        isToolOnly,
202→      };
203→    }
204→
205→    if (msg.type === "result") {
206→      const result = msg as ClaudeResult;
207→      const summary = result.is_error
208→        ? `Error: ${result.error}`
209→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
210→      return {
211→        id: nextId(),
212→        role: "system",
213→        content: summary,
214→        timestamp: Date.now(),
215→      };
216→    }
217→
218→    if (msg.type === "control_request") {
219→      const cr = msg as ClaudeControlRequest;
220→
221→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
222→      if (cr.request.tool_name === "AskUserQuestion") {
223→        const input = cr.request.input as { questions?: UserQuestion[] };
224→        const questions = Array.isArray(input.questions) ? input.questions : [];
225→        return {
226→          id: nextId(),
227→          role: "system",
228→          content: "Question from Claude",
229→          timestamp: Date.now(),
230→          userQuestion: {
231→            requestId: cr.request_id,
232→            questions,
233→          },
234→        };
235→      }
236→
237→      return {
238→        id: nextId(),
239→        role: "system",
240→        content: `Tool approval requested: ${cr.request.tool_name}`,
241→        timestamp: Date.now(),
242→        controlRequest: {
243→          id: cr.request_id,
244→          tool_name: cr.request.tool_name,
245→          input: cr.request.input,
246→          description: cr.request.description,
247→        },
248→      };
249→    }
250→  }
251→
252→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
253→    return {
254→      id: nextId(),
255→      role: "system",
256→      content: `Error: ${relayMsg.error}`,
257→      timestamp: Date.now(),
258→    };
259→  }
260→
261→  return null;
262→}
263→
264→/** Console logger with [thos] prefix for easy filtering. */
265→function log(...args: unknown[]) {
266→  console.log("[thos-ws]", ...args);
267→}
268→
269→export function useWebSocket() {
270→  const wsRef = useRef<WebSocket | null>(null);
271→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
272→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
273→  const closingRef = useRef(false);
274→  const [connected, setConnected] = useState(false);
275→  /** True once we've received the initial agent_list from the server. */
276→  const [initialLoadDone, setInitialLoadDone] = useState(false);
277→
278→  // Multi-agent state
279→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
280→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
281→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
282→
283→  // Task state
284→  const [tasks, setTasks] = useState<Task[]>([]);
285→
286→  // Workspace state
287→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
288→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
289→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
290→
291→  // Per-agent deduplication: track count of processed messages per agent
292→  // to avoid duplicating messages already in local state during history replay.
293→  const processedCountRef = useRef<Map<string, number>>(new Map());
294→
295→  // Track which agents have had their history loaded (lazy loading).
296→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
297→
298→  /** Immutably update a single agent's state in the Map. */
299→  const updateAgent = useCallback(
300→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
301→      setAgents((prev) => {
302→        const existing = prev.get(agentId);
303→        if (!existing) return prev;
304→        const next = new Map(prev);
305→        next.set(agentId, updater(existing));
306→        return next;
307→      });
308→    },
309→    []
310→  );
311→
312→  const connect = useCallback(() => {
313→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
314→    if (wsRef.current) {
315→      wsRef.current.close();
316→      wsRef.current = null;
317→    }
318→
319→    // Reset dedup counts on new connection — server will send fresh history
320→    processedCountRef.current.clear();
321→    setInitialLoadDone(false);
322→    setLoadedAgents(new Set());
323→
324→    log("connecting to", WS_URL);
325→    const ws = new WebSocket(WS_URL);
326→    wsRef.current = ws;
327→
328→    ws.onopen = () => {
329→      log("connected");
330→      setConnected(true);
331→    };
332→
333→    ws.onclose = () => {
334→      log("disconnected, closingRef =", closingRef.current);
335→      setConnected(false);
336→      wsRef.current = null;
337→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
338→      if (closingRef.current) return;
339→      // Reconnection guard: clear any existing timer before scheduling
340→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
341→      log("scheduling reconnect in 2s");
342→      reconnectTimer.current = setTimeout(() => connect(), 2000);
343→    };
344→
345→    ws.onerror = (e) => {
346→      log("error", e);
347→      // onclose will fire after onerror, which triggers reconnect
348→    };
349→
350→    ws.onmessage = (event) => {
351→      let data: ServerMessage;
352→      try {
353→        data = JSON.parse(event.data as string);
354→      } catch {
355→        return;
356→      }
357→
358→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
359→
360→      // ── workspace_list: full workspace list from server ──
361→      if (data.type === "workspace_list") {
362→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
363→        log("workspace_list:", wsList.length, "workspaces");
364→        setWorkspaces(wsList);
365→        return;
366→      }
367→
368→      // ── directory_listing: response to browse_directory ──
369→      if (data.type === "directory_listing") {
370→        const listing = data as { path: string; entries: DirectoryEntry[] };
371→        log("directory_listing:", listing.path, listing.entries.length, "entries");
372→        setDirectoryListing({ path: listing.path, entries: listing.entries });
373→        return;
374→      }
375→
376→      // ── task_list: full task list from server ──
377→      if (data.type === "task_list") {
378→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
379→        setTasks((data as ServerTaskList).tasks);
380→        return;
381→      }
382→
383→      // ── task_updated: single task changed ──
384→      if (data.type === "task_updated") {
385→        const updated = (data as ServerTaskUpdated).task;
386→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
387→        return;
388→      }
389→
390→      // ── task_deleted: remove task ──
391→      if (data.type === "task_deleted") {
392→        const deletedId = (data as ServerTaskDeleted).taskId;
393→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
394→        return;
395→      }
396→
397→      // ── message_history: replay full history from server ──
398→      if (data.type === "message_history") {
399→        const historyMsg = data as ServerMessageHistory;
400→        const agentId = historyMsg.agentId;
401→        const serverMessages = historyMsg.messages;
402→        log("message_history:", agentId, serverMessages.length, "raw msgs");
403→
404→        // Convert all server messages to ChatMessages + extract raw Claude messages
405→        const chatMessages: ChatMessage[] = [];
406→        const rawMessages: ClaudeMessage[] = [];
407→        for (const sm of serverMessages) {
408→          if (sm.type === "relay") {
409→            rawMessages.push(sm.message);
410→          }
411→          const cm = relayChatMessage(agentId, sm);
412→          if (cm) chatMessages.push(cm);
413→        }
414→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
415→
416→        // Always replace local messages with server history (source of truth).
417→        setAgents((prev) => {
418→          const existing = prev.get(agentId);
419→          if (!existing) {
420→            log("message_history:", agentId, "agent not in map yet, creating");
421→            const next = new Map(prev);
422→            next.set(agentId, {
423→              status: "idle",
424→              messages: chatMessages,
425→              rawMessages,
426→              label: "",
427→              tmuxSession: null,
428→              createdAt: 0,
429→            });
430→            return next;
431→          }
432→          const next = new Map(prev);
433→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
434→          return next;
435→        });
436→
437→        processedCountRef.current.set(agentId, chatMessages.length);
438→        setLoadedAgents((prev) => {
439→          if (prev.has(agentId)) return prev;
440→          const next = new Set(prev);
441→          next.add(agentId);
442→          return next;
443→        });
444→        return;
445→      }
446→
447→      // ── history_cleared: wipe local messages for this agent ──
448→      if (data.type === "history_cleared") {
449→        updateAgent(data.agentId, (prev) => ({
450→          ...prev,
451→          messages: [],
452→          rawMessages: [],
453→        }));
454→        processedCountRef.current.set(data.agentId, 0);
455→        return;
456→      }
457→
458→      // ── cli_disconnected: show system message ──
459→      if (data.type === "cli_disconnected") {
460→        updateAgent(data.agentId, (prev) => ({
461→          ...prev,
462→          messages: [
463→            ...prev.messages,
464→            {
465→              id: nextId(),
466→              role: "system",
467→              content: "CLI session ended",
468→              timestamp: Date.now(),
469→            },
470→          ],
471→        }));
472→        return;
473→      }
474→
475→      // ── cli_connected: show system message ──
476→      if (data.type === "cli_connected") {
477→        updateAgent(data.agentId, (prev) => ({
478→          ...prev,
479→          messages: [
480→            ...prev.messages,
481→            {
482→              id: nextId(),
483→              role: "system",
484→              content: "CLI reconnected",
485→              timestamp: Date.now(),
486→            },
487→          ],
488→        }));
489→        return;
490→      }
491→
492→      // ── agent_list: reconcile sidebar state from server ──
493→      if (data.type === "agent_list") {
494→        const serverAgents = data.agents as AgentInfo[];
495→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
496→        setAgents((prev) => {
497→          const next = new Map(prev);
498→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
499→
500→          // Update or add agents from server
501→          for (const info of serverAgents) {
502→            const existing = next.get(info.agentId);
503→            if (existing) {
504→              next.set(info.agentId, {
505→                ...existing,
506→                status: info.status,
507→                tmuxSession: info.tmuxSession,
508→                label: info.label,
509→                model: info.model ?? existing.model,
510→                pinned: info.pinned ?? false,
511→                iceboxed: info.iceboxed ?? false,
512→              });
513→            } else {
514→              next.set(info.agentId, {
515→                status: info.status,
516→                messages: [],
517→                rawMessages: [],
518→                label: info.label,
519→                tmuxSession: info.tmuxSession,
520→                createdAt: info.createdAt,
521→                model: info.model ?? undefined,
522→                pinned: info.pinned ?? false,
523→                iceboxed: info.iceboxed ?? false,
524→              });
525→            }
526→          }
527→
528→          // Remove agents no longer on the server
529→          for (const id of next.keys()) {
530→            if (!serverIds.has(id)) {
531→              next.delete(id);
532→            }
533→          }
534→
535→          return next;
536→        });
537→        setAgentOrder(serverAgents.map((a) => a.agentId));
538→        setInitialLoadDone(true);
539→
540→        // Auto-select the first agent on initial load when nothing is selected
541→        setActiveAgentId((prev) => {
542→          if (prev !== null) return prev;
543→          if (serverAgents.length === 0) return null;
544→          return serverAgents[0].agentId;
545→        });
546→        return;
547→      }
548→
549→      // ── spawned: auto-select the newly created agent ──
550→      if (data.type === "spawned") {
551→        setActiveAgentId(data.agentId);
552→        return;
553→      }
554→
555→      // ── status: update a specific agent's status ──
556→      if (data.type === "status") {
557→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
558→        return;
559→      }
560→
561→      // ── error: append to agent's message list ──
562→      if (data.type === "error") {
563→        sfxError();
564→        updateAgent(data.agentId, (prev) => ({
565→          ...prev,
566→          messages: [
567→            ...prev.messages,
568→            {
569→              id: nextId(),
570→              role: "system",
571→              content: `Error: ${data.error}`,
572→              timestamp: Date.now(),
573→            },
574→          ],
575→        }));
576→        // Track processed count for dedup
577→        processedCountRef.current.set(
578→          data.agentId,
579→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
580→        );
581→        return;
582→      }
583→
584→      // ── relay: append claude message to agent's history ──
585→      if (data.type === "relay") {
586→        const agentId = data.agentId;
587→        const rawMsg = data.message;
588→        const chatMsg = relayChatMessage(agentId, data);
589→
590→        // SFX: play a sound for each tool call in the message
591→        if (chatMsg?.toolCalls?.length) {
592→          // Play SFX for the first mapped tool (avoids overlapping sounds in multi-tool messages)
593→          const first = chatMsg.toolCalls.find((tc) => tc.name);
594→          if (first) sfxTool(first.name);
595→        }
596→
597→        // SFX: result done / error
598→        if (rawMsg.type === "result") {
599→          const result = rawMsg as ClaudeResult;
600→          if (result.is_error) sfxError();
601→          else sfxDone();
602→        }
603→
604→        // SFX: control request (tool approval / question)
605→        if (rawMsg.type === "control_request") {
606→          sfxQuestion();
607→        }
608→
609→        // SFX: session start
610→        if (rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init") {
611→          sfxBegin();
612→        }
613→
614→        // Capture model from system/init
615→        const initModel =
616→          rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init"
617→            ? (rawMsg as ClaudeSystemInit).model
618→            : undefined;
619→
620→        updateAgent(agentId, (prev) => ({
621→          ...prev,
622→          rawMessages: [...prev.rawMessages, rawMsg],
623→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
624→          ...(initModel ? { model: initModel } : {}),
625→        }));
626→        if (chatMsg) {
627→          // Track processed count for dedup
628→          processedCountRef.current.set(
629→            agentId,
630→            (processedCountRef.current.get(agentId) ?? 0) + 1
631→          );
632→        }
633→        return;
634→      }
635→    };
636→  }, [updateAgent]);
637→
638→  useEffect(() => {
639→    closingRef.current = false;
640→    connect();
641→    return () => {
642→      closingRef.current = true;
643→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
644→      wsRef.current?.close();
645→    };
646→  }, [connect]);
647→
648→  const send = useCallback((data: object) => {
649→    if (wsRef.current?.readyState === WebSocket.OPEN) {
650→      wsRef.current.send(JSON.stringify(data));
651→    }
652→  }, []);
653→
654→  // Request history for the active agent if not already loaded.
655→  useEffect(() => {
656→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
657→    log("requesting history for", activeAgentId);
658→    send({ type: "request_history", agentId: activeAgentId });
659→  }, [activeAgentId, loadedAgents, send]);
660→
661→  const spawnAgent = useCallback(
662→    (prompt: string, model?: string) => {
663→      send({ type: "spawn", prompt, ...(model ? { model } : {}) });
664→    },
665→    [send]
666→  );
667→
668→  const sendMessage = useCallback(
669→    (content: string) => {
670→      if (!activeAgentId) return;
671→      // Optimistically add user message to local state
672→      updateAgent(activeAgentId, (prev) => ({
673→        ...prev,
674→        messages: [
675→          ...prev.messages,
676→          {
677→            id: nextId(),
678→            role: "user",
679→            content,
680→            timestamp: Date.now(),
681→          },
682→        ],
683→      }));
684→      send({ type: "send_message", agentId: activeAgentId, content });
685→      sfxSend();
686→    },
687→    [send, activeAgentId, updateAgent]
688→  );
689→
690→  const respondToControl = useCallback(
691→    (requestId: string, allow: boolean) => {
692→      if (!activeAgentId) return;
693→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
694→      updateAgent(activeAgentId, (prev) => ({
695→        ...prev,
696→        messages: prev.messages.map((m) =>
697→          m.controlRequest?.id === requestId
698→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
699→            : m
700→        ),
701→      }));
702→    },
703→    [send, activeAgentId, updateAgent]
704→  );
705→
706→  /** Respond to an AskUserQuestion control request with the user's selections. */
707→  const respondToUserQuestion = useCallback(
708→    (requestId: string, answers: Record<string, string>) => {
709→      if (!activeAgentId) return;
710→      send({
711→        type: "control_response",
712→        agentId: activeAgentId,
713→        request_id: requestId,
714→        allow: true,
715→        answers,
716→      });
717→      updateAgent(activeAgentId, (prev) => ({
718→        ...prev,
719→        messages: prev.messages.map((m) =>
720→          m.userQuestion?.requestId === requestId
721→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
722→            : m
723→        ),
724→      }));
725→    },
726→    [send, activeAgentId, updateAgent]
727→  );
728→
729→  // ── Agent management actions ──────────────────────────────────────────────
730→
731→  const killAgent = useCallback(
732→    (agentId: string) => {
733→      send({ type: "kill_agent", agentId });
734→    },
735→    [send]
736→  );
737→
738→  const deleteAgent = useCallback(
739→    (agentId: string) => {
740→      send({ type: "delete_agent", agentId });
741→      // Deselect if we just deleted the active agent
742→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
743→    },
744→    [send]
745→  );
746→
747→  const renameAgent = useCallback(
748→    (agentId: string, label: string) => {
749→      send({ type: "rename_agent", agentId, label });
750→    },
751→    [send]
752→  );
753→
754→  const clearHistory = useCallback(
755→    (agentId: string) => {
756→      send({ type: "clear_history", agentId });
757→    },
758→    [send]
759→  );
760→
761→  const pinAgent = useCallback(
762→    (agentId: string, pinned: boolean) => {
763→      send({ type: "pin_agent", agentId, pinned });
764→    },
765→    [send]
766→  );
767→
768→  const iceboxAgent = useCallback(
769→    (agentId: string, iceboxed: boolean) => {
770→      send({ type: "icebox_agent", agentId, iceboxed });
771→    },
772→    [send]
