        const agent = agents.get(ctxMenu.agentId);
        if (!agent) return null;
        return createPortal(
          <div
            ref={menuRef}
            className="fixed z-[9999] min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
            style={{ left: ctxMenu.x, top: ctxMenu.y }}
