              label={agent.iceboxed ? "Un-icebox" : "Icebox"}
              onClick={() => {
                onIcebox(ctxMenu.agentId, !agent.iceboxed);
                closeMenu();
              }}
            />
            <ContextMenuItem
              label="Rename"
              onClick={() => {
                setRenamingId(ctxMenu.agentId);
                closeMenu();
              }}
            />
            {KILLABLE.has(agent.status) && (
              <ContextMenuItem
                label="Kill"
                onClick={() => {
                  onKill(ctxMenu.agentId);
                  closeMenu();
                }}
              />
            )}
            <ContextMenuItem
              label="Clear History"
              onClick={() => {
                onClearHistory(ctxMenu.agentId);
                closeMenu();
              }}
            />
            <div className="my-1 border-t" />
            <ContextMenuItem
              label="Delete"
              destructive
              onClick={() => {
                closeMenu();
                if (confirm("Delete this agent? This cannot be undone.")) {
                  onDelete(ctxMenu.agentId);
                }
              }}
            />
          </div>,
          document.body
        );
      })()}
    </div>
  );
}

/** A single item in the context menu. */
function ContextMenuItem({
  label,
  onClick,
  destructive,
}: {
  label: string;
  onClick: () => void;
  destructive?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "flex w-full px-3 py-1.5 text-xs transition-colors",
        destructive
          ? "text-red-500 hover:bg-red-500/10"
          : "hover:bg-accent"
      )}
    >
      {label}
    </button>
  );
}

/** Inline input for renaming an agent. */
function RenameInput({
  initialValue,
  onConfirm,
  onCancel,
}: {
  initialValue: string;
  onConfirm: (value: string) => void;
  onCancel: () => void;
}) {
  const [value, setValue] = useState(initialValue);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  function handleKeyDown(e: React.KeyboardEvent) {
    e.stopPropagation();
    if (e.key === "Enter") {
      const trimmed = value.trim();
      if (trimmed) onConfirm(trimmed);
      else onCancel();
    } else if (e.key === "Escape") {
      onCancel();
    }
  }

  return (
    <input
      ref={inputRef}
      type="text"
      value={value}
      onChange={(e) => setValue(e.target.value)}
      onKeyDown={handleKeyDown}
      onBlur={() => {
        const trimmed = value.trim();
        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
        else onCancel();
      }}
      onClick={(e) => e.stopPropagation()}
      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
    />
  );
}

